trigger OpportunityTrigger on Opportunity (before insert, before update) {
    for (Opportunity opp : Trigger.new) {
        if (opp.CloseDate != null && opp.Next_Step_Due__c == null) {
            opp.Next_Step_Due__c = opp.CloseDate.addDays(-7);
        }
        if (opp.Amount != null && opp.Amount > 100000) {
            opp.Deal_Tier__c = 'Strategic';
        }
    }
}

trigger LeadTrigger on Lead (before insert, before update) {
    for (Lead ld : Trigger.new) {
        if (String.isBlank(ld.Status)) {
            ld.Status = 'Open - Not Contacted';
        }
        ld.Normalized_Domain__c = LeadHelper.domainOf(ld.Email);
    }
}

trigger LeadAssignmentTrigger on Lead (after insert, after update) {
    LeadAssignmentService.route(Trigger.newMap.values());
}

trigger AccountTrigger on Account (before insert, before update) {
    for (Account acc : Trigger.new) {
        acc.Normalized_Name__c = AccountHelper.normalize(acc.Name);
    }
}

trigger ContactSyncTrigger on Contact (after insert, after update) {
    for (Contact c : Trigger.new) {
        c.Lifecycle_Stage__c = 'Synced';
    }
}
